<pre><code>publishing {
    publications {
        maven(MavenPublication) {
            artifactId = 'gtm'
            from components.java
        }
    }
    repositories {
        maven {
            url 'https://nexus.grandtheftmc.net/content/repositories/releases/'
            credentials {
                username mavenUser
                password mavenPassword
            }
        }
    }
}
</code></pre>

