      // continue ...
      // 3. Only then continue to next promise
      resolve('now it is finished');
    }).catch( err =&gt; reject(err) );
  });
}

var finalPromise = function() {
  return new Promise( (resolve, reject) =&gt; {
    console.log('finalPromise');
    resolve();
  });
}

promiseA()
