To execute your for loop when the button is clicked, you need to wrap your existing loop inside a function and attach that function to the button's click event. Here's how you can do it:

1. Create a function that contains your for loop.
2. Use `document.getElementById` to select your button and set an event listener for the 'click' event that calls your function.

Here's how you would structure your code:

```javascript
var restaurantsOne = ["Nandos", "King Rooster", "Chick-Fil-A", "Dominos", "KFC"];
var restaurantsTwo = ["Nandos","MacDonalds","Burger King","KFC","Pizza Hut"];

function searchRestaurants() {
  for (var i = 0; i < restaurantsOne.length; i++) {
    for (var j = 0; j < restaurantsTwo.length; j++) {
      if (restaurantsOne[i] === restaurantsTwo[j]) {
        console.log(restaurantsOne[i]);
      }
    }
  }
}

document.getElementById('search').addEventListener('click', searchRestaurants);
```

