}) === index)

// Remove invalid
.filter(function(event){
    if (~this.indexOf(event.id)) {
        return false;
    } else {
        return true;
    }
}, result[2])

// Sort array by date
.sort(function(a, b) {
    return new Date(a.start_time).getTime() - new Date(b.start_time).getTime();
})

// Filter and collect promoted events
.reduce((acc, event) => {
    if (~this.indexOf(event.id)) {
        event.promoted = true;
        acc.promoted.push(event); // Collect promoted events
    } else {
        acc.nonPromoted.push(event);
    }
    return acc;
}, { promoted: [], nonPromoted: [] })
.then(result => result.promoted.concat(result.nonPromoted)); // Combine promoted and non-promoted arrays
```

In this approach, the `reduce` method is used to create two separate arrays: one for promoted events and one for non-promoted events. Finally, you concatenate both arrays to have the promoted events at the top.

